import { existsSync, readFileSync } from "node:fs";
import { beforeAll, describe, expect, it } from "vitest";
import { createEngine, initEngine, type Engine } from "../src/engine/engine";

// Generated by `pnpm animations` (scripts/animations/build.mjs).
const root = new URL("../", import.meta.url);
const wasm = readFileSync(new URL("src/engine/vendor/lumetrope_wasm_bg.wasm", root));
const animPath = (name: string) => new URL(`public/animations/${name}.lottie`, root);
const posterPath = (name: string) => new URL(`public/posters/${name}.webp`, root);

const FEATURES = ["timeline", "state-machines", "mcp", "wasm-engine", "version-history", "export", "desktop", "themes"];

const FILES: { name: string; machine: string; initial: string; w: number; h: number }[] = [
  { name: "lumi", machine: "Lumi", initial: "Idle", w: 480, h: 480 },
  ...FEATURES.map((f) => ({ name: `icon-${f}`, machine: "Icon", initial: "Rest", w: 96, h: 96 })),
  { name: "zoetrope", machine: "Zoetrope", initial: "B1", w: 720, h: 420 },
  { name: "cta", machine: "Cta", initial: "Rest", w: 220, h: 56 },
  { name: "logo", machine: "Logo", initial: "Idle", w: 40, h: 40 },
  { name: "sm-explainer", machine: "Explainer", initial: "Off", w: 480, h: 360 },
];

type Snap = { state: string; frame: number; tweening: boolean; inputs: Record<string, unknown> };

function load(name: string): Engine {
  const e = createEngine();
  e.load_file(`${name}.lottie`, new Uint8Array(readFileSync(animPath(name))));
  return e;
}
const snap = (s: string): Snap => JSON.parse(s);
const start = (e: Engine, m: string) => snap(e.sm_start(m)).state;
const set = (e: Engine, input: string, v: unknown) => snap(e.sm_set_input(input, JSON.stringify(v))).state;
const fire = (e: Engine, input: string) => snap(e.sm_set_input(input, "null")).state;
const tick = (e: Engine, secs: number) => snap(e.sm_tick(secs)).state;

beforeAll(async () => {
  await initEngine(wasm);
});

describe.each(FILES)("$name.lottie", ({ name, machine, initial, w, h }) => {
  it("exists, loads with load_file and has the right size", () => {
    expect(existsSync(animPath(name))).toBe(true);
    const info = JSON.parse(load(name).info());
    expect([info.w, info.h]).toEqual([w, h]);
  });

  it(`has a state machine "${machine}" that starts in ${initial}`, () => {
    const e = load(name);
    const machines = JSON.parse(e.project_json()).stateMachines;
    expect(Object.keys(machines)).toEqual([machine]);
    expect(start(e, machine)).toBe(initial);
  });

  it("renders visible artwork on its first frame", () => {
    const px = load(name).render(0, w, h);
    let painted = 0;
    for (let i = 3; i < px.length; i += 4) if (px[i] > 0) painted++;
    expect(painted).toBeGreaterThan((w * h) / 20);
  });

  it("has a non-empty poster", () => {
    expect(existsSync(posterPath(name))).toBe(true);
    const bytes = readFileSync(posterPath(name));
    expect(bytes.length).toBeGreaterThan(100);
    expect(bytes.subarray(0, 4).toString("latin1")).toBe("RIFF");
    expect(bytes.subarray(8, 12).toString("latin1")).toBe("WEBP");
  });
});

describe("Lumi", () => {
  it("is 30 fps", () => {
    expect(JSON.parse(load("lumi").info()).fr).toBe(30);
  });

  it("waves while hovered and returns to Idle", () => {
    const e = load("lumi");
    start(e, "Lumi");
    expect(set(e, "hover", true)).toBe("Wave");
    expect(set(e, "hover", false)).toBe("Idle");
  });

  it("looks left and right with the look input", () => {
    const e = load("lumi");
    start(e, "Lumi");
    expect(set(e, "look", -0.8)).toBe("LookLeft");
    expect(set(e, "look", 0)).toBe("Idle");
    expect(set(e, "look", 0.8)).toBe("LookRight");
    expect(set(e, "look", 0.2)).toBe("Idle");
  });

  it("jumps on poke from any state, then settles back to Idle", () => {
    const e = load("lumi");
    start(e, "Lumi");
    expect(fire(e, "poke")).toBe("Jump");
    expect(tick(e, 2)).toBe("Idle");
    expect(set(e, "hover", true)).toBe("Wave");
    expect(fire(e, "poke")).toBe("Jump");
    set(e, "hover", false);
    expect(tick(e, 2)).toBe("Idle");
  });

  it("cheers on the cheer event, then returns to Idle", () => {
    const e = load("lumi");
    start(e, "Lumi");
    expect(fire(e, "cheer")).toBe("Cheer");
    expect(tick(e, 3)).toBe("Idle");
  });

  it("sleeps when sleepy and tweens back awake", () => {
    const e = load("lumi");
    start(e, "Lumi");
    expect(set(e, "sleepy", true)).toBe("Sleep");
    expect(fire(e, "poke")).toBe("Jump");
    tick(e, 2);
    expect(snap(e.sm_snapshot()).state).toBe("Sleep");
    const s = snap(e.sm_set_input("sleepy", "false"));
    expect(s.tweening).toBe(true);
    expect(tick(e, 0.4)).toBe("Idle");
  });

  it("clicking the body fires poke", () => {
    const e = load("lumi");
    start(e, "Lumi");
    tick(e, 0.1);
    expect(snap(e.sm_pointer("click", 240, 300)).state).toBe("Jump");
  });
});

describe("Icons", () => {
  it.each(FEATURES)("icon-%s goes Active on hover and back to Rest", (f) => {
    const e = load(`icon-${f}`);
    start(e, "Icon");
    set(e, "hover", true);
    expect(tick(e, 0.25)).toBe("Active");
    set(e, "hover", false);
    expect(tick(e, 0.25)).toBe("Rest");
  });

  it.each(FEATURES)("icon-%s sets hover from pointer enter/exit", (f) => {
    const e = load(`icon-${f}`);
    start(e, "Icon");
    e.sm_pointer("enter", 48, 48);
    expect(tick(e, 0.25)).toBe("Active");
    e.sm_pointer("exit", -1, -1);
    expect(tick(e, 0.25)).toBe("Rest");
  });
});

describe("Zoetrope", () => {
  it("follows scroll progress through B1..B4", () => {
    const e = load("zoetrope");
    start(e, "Zoetrope");
    expect(set(e, "progress", 0.6)).toBe("B3");
    expect(set(e, "progress", 0.3)).toBe("B2");
    expect(set(e, "progress", 0.9)).toBe("B4");
    expect(set(e, "progress", 0.1)).toBe("B1");
  });

  it("spins on click and lands back on the current benefit", () => {
    const e = load("zoetrope");
    start(e, "Zoetrope");
    set(e, "progress", 0.6);
    expect(snap(e.sm_pointer("click", 360, 300)).state).toBe("Spin");
    expect(tick(e, 3)).toBe("B3");
  });
});

describe("Cta", () => {
  it("hovers, presses and finishes with a check mark", () => {
    const e = load("cta");
    start(e, "Cta");
    expect(set(e, "hover", true)).toBe("Hover");
    expect(fire(e, "press")).toBe("Pressed");
    expect(fire(e, "done")).toBe("Done");
    set(e, "hover", false);
    expect(tick(e, 3)).toBe("Rest");
  });
});

describe("Logo", () => {
  it("speeds up on hover", () => {
    const e = load("logo");
    start(e, "Logo");
    expect(set(e, "hover", true)).toBe("Fast");
    expect(set(e, "hover", false)).toBe("Idle");
  });
});

describe("Explainer", () => {
  it("toggles on click", () => {
    const e = load("sm-explainer");
    start(e, "Explainer");
    expect(snap(e.sm_pointer("click", 180, 120)).state).toBe("SwitchOn");
    expect(tick(e, 2)).toBe("On");
    expect(snap(e.sm_pointer("click", 180, 120)).state).toBe("SwitchOff");
    expect(tick(e, 2)).toBe("Off");
  });
});
